export const AS_OF='2026-09-22';
export const products=['KYC Data','KYC Documents','Business Verification','Fraud Intelligence'];
const names=['Northstar Payments','Meridian Marketplace','Atlas Remit','Harbor Digital Bank','Cedar Wealth','Orbit Exchange','Lumen Lending','Juniper Commerce','Nova Payroll','Bridgeway FX','Summit Capital','Cobalt Wallet','Evergreen Credit','Vela Trading','Mosaic Pay','Pinnacle Markets','Aster Finance','Cove Insurance','Rivet Banking','Solstice Commerce','Tandem Remit','Willow Invest','Beacon Digital','Arcadia Pay'];
const owners=['Alex Chen','Priya Shah','Jordan Lee','Sam Rivera'];
export const accounts=names.map((name,i)=>{
 const kind=i%6;const previous=40000+i*9300;const growth=[.34,-.24,.28,.07,-.04,.18][kind];
 return {id:`A${String(i+1).padStart(3,'0')}`,name,industry:['Payments','Marketplaces','Remittance','Banking','Wealth','Trading'][kind],region:['North America','Europe','APAC'][i%3],segment:i%3===0?'Enterprise':i%3===1?'Mid-market':'Growth',arr:[420000,285000,180000,720000,96000,240000][kind]+Math.floor(i/6)*24000,ae:owners[i%4],csm:owners[(i+1)%4],renewalDays:[112,38,67,145,24,91][kind]+Math.floor(i/6)*3,lastTouchDays:[19,26,15,8,31,12][kind],previousVolume:previous,currentVolume:Math.round(previous*(1+growth)),successPrevious:96,successCurrent:[97,88,95,97,94,96][kind],reviewRate:[3,13,4,2,6,4][kind],tickets:[2,12,3,1,5,2][kind],countries:5+i%8,newCountries:[3,0,2,0,0,1][kind],products:kind===0?['KYC Data']:kind===1?['KYC Data','KYC Documents']:kind===2?['KYC Data','Business Verification']:kind===3?[...products]:['KYC Data','KYC Documents','Fraud Intelligence'],eligible:kind===4?['KYC Data','KYC Documents','Fraud Intelligence']:[...products],usageAgeDays:kind===2?12:1,crmAgeDays:i===14?18:2,ownerMissing:i===20,stage:['Discovery','Proposal','Qualification','None','Negotiation','Discovery'][kind],opportunity:[84000,48000,56000,0,22000,60000][kind],closeDays:[60,45,80,0,21,50][kind],renewalStatus:kind===1?'At risk':kind===4?'In discussion':'Not started',months:Array.from({length:6},(_,m)=>Math.round((m<3?previous:Math.round(previous*(1+growth)))/3*[.95,1,1.05][m%3])),};
});
export function growth(a){return a.previousVolume>0?(a.currentVolume-a.previousVolume)/a.previousVolume:null}
export function quality(a){return [a.usageAgeDays>7?'Usage feed is more than 7 days old':null,a.crmAgeDays>14?'CRM is more than 14 days old':null,a.ownerMissing?'CRM account owner is missing':null,a.previousVolume<=0?'No valid baseline volume':null].filter(Boolean)}
export function signals(a){const g=growth(a),q=quality(a);const friction=a.successCurrent-a.successPrevious<=-5||a.tickets>=10;const decline=g!==null&&g<=-.15;const whitespace=a.eligible.filter(p=>!a.products.includes(p));let motion='Monitor',score=20,reasons=[],action='Review account at the next monthly portfolio review',role='CSM',owner=a.csm,due=14;
 if(q.length){motion='Data quality';score=75;reasons=q;action='Validate source records and restore trustworthy signals before commercial outreach';role='RevOps';owner='Tejas Singh';due=2}
 else if(friction||decline||a.renewalDays<=45){motion='Retention';score=Math.min(100,40+(friction?25:0)+(decline?20:0)+(a.renewalDays<=45?15:0));reasons=[friction?`Verification friction: ${a.successCurrent}% success, ${a.tickets} open tickets`:null,decline?`Volume ${percent(g)} versus prior 90 days`:null,a.renewalDays<=45?`Renewal in ${a.renewalDays} days`:null].filter(Boolean);action=friction?'Run a customer-health review with support; agree a recovery plan before renewal':'Confirm renewal intent, stakeholders and mutual next steps';due=friction?2:5}
 else if(g>=.2&&whitespace.length&&a.newCountries>=1){motion='Expansion';score=Math.min(90,40+Math.round(g*50)+a.newCountries*5+(a.arr>=300000?10:0));reasons=[`Volume ${percent(g)} versus prior 90 days`,`${a.newCountries} new markets; ${whitespace.length} eligible products not adopted`];action='Validate new-market needs with the account team; confirm product fit and agree the next expansion milestone';role='AE';owner=a.ae;due=5}
 else {reasons=['No urgent rule triggered; maintain the account cadence']}
 return {motion,score,reasons,action,owner,role,due,whitespace,priority:score>=80?'High':score>=50?'Medium':'Low',quality:q};}
export const percent=v=>v===null?'Unavailable':`${v>=0?'+':''}${Math.round(v*100)}%`;
export const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
export const shortMoney=v=>v>=1e6?`$${(v/1e6).toFixed(2)}m`:`$${Math.round(v/1000)}k`;
export const probabilities={Discovery:.2,Qualification:.35,Proposal:.6,Negotiation:.8,None:0};
export function metrics(rows){return {arr:rows.reduce((s,a)=>s+a.arr,0),renewal:rows.filter(a=>a.renewalDays<=90).reduce((s,a)=>s+a.arr,0),risk:rows.filter(a=>signals(a).motion==='Retention').reduce((s,a)=>s+a.arr,0),pipeline:rows.reduce((s,a)=>s+a.opportunity*probabilities[a.stage],0),quality:rows.filter(a=>quality(a).length).length,expansion:rows.filter(a=>signals(a).motion==='Expansion').length};}
export function brief(a){const s=signals(a);return {summary:`${a.name} is routed to ${s.motion.toLowerCase()} (${s.priority.toLowerCase()} priority, ${s.score}/100). ${s.reasons.join('. ')}.`,commercial:`Annual contract value is ${money(a.arr)}; renewal is in ${a.renewalDays} days. ${a.products.length} of ${a.eligible.length} relevant product families are adopted.`,action:`${s.owner} (${s.role}): ${s.action}. Target: ${s.due} business days.`,caution:s.quality.length?'Stale or incomplete data blocks an expansion recommendation. Validate the source first.':'These signals suggest a review, not a confirmed buying intent, churn probability or causal diagnosis.',evidence:['Rules & routing','Commercial context','Product adoption','Usage & customer health']};}
export function filtered(rows,{query='',segment='All segments',motion='All motions',owner='All owners'}={}){return rows.filter(a=>(a.name+' '+a.id+' '+a.industry).toLowerCase().includes(query.toLowerCase())&&(segment==='All segments'||a.segment===segment)&&(motion==='All motions'||signals(a).motion===motion)&&(owner==='All owners'||signals(a).owner===owner)).sort((a,b)=>signals(b).score-signals(a).score||b.arr-a.arr)}

export function accountCSV(rows,state={}){const fields=['Account ID','Account','Segment','ARR USD','Motion','Priority points','Owner','Next action','Status','Synthetic'];return [fields,...rows.map(a=>{const s=signals(a);return [a.id,a.name,a.segment,a.arr,s.motion,s.score,state[a.id]?.owner||s.owner,s.action,state[a.id]?.status||'To do','Yes']})].map(r=>r.map(v=>{let cell=String(v);if(/^[=+@\-]/.test(cell))cell="'"+cell;return '"'+cell.replaceAll('"','""')+'"'}).join(',')).join('\r\n')}
